    const marker2 = "\nPAGEEOF\nexit 0";
    const p1 = decoded.indexOf(marker1);
    const p2 = decoded.lastIndexOf(marker2);
    if (p1 === -1 || p2 === -1) return "<h1>Error loading HTML</h1>";
    let html = decoded.substring(p1 + marker1.length, p2);

