function genCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let res = "";
  for (let i = 0; i < 9; i++) res += chars.charAt(Math.floor(Math.random() * chars.length));
  return res;
}

let store = {
  vouchers: [["TESTVOUCH", 0, 0, 0, 0, 1440, 0, "", "", "", "", 0]],
  packages: [
    ["1 Day 5Mbps", 20, 5000, 5000, 1440],
    ["3 Days 10Mbps", 50, 10000, 10000, 4320],
    ["7 Days 15Mbps", 100, 15000, 15000, 10080],
    ["30 Days 20Mbps", 300, 20000, 20000, 43200]
  ],
  routers: [],
  brand: "SHAMIM WiFi",
  lanif: "br-lan",
  adminId: "admin",
  adminPw: "shamim123",
  bkash: "01638073621",
  nagad: "",
  paynote: "Send money then SMS TrxID to 01638073621",
  portalMsg: "স্বাগতম! দ্রুত ও নিরবচ্ছিন্ন ইন্টারনেট সেবা",
  hotspotSharing: "disabled",
  currencyCode: "BDT",
  currencySymbol: "৳",
  rebootType: "disabled",
  rebootDay: "Sunday",
  rebootHH: 4,
  rebootMM: 0
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const ua = (request.headers.get("User-Agent") || "").toLowerCase();
    const isWgetOrCurl = ua.includes("wget") || ua.includes("curl");
    const isDownload = url.searchParams.has("download") || url.pathname.startsWith("/download");

    // ১. রাউটার থিম ডাউনলোড (/theme)
    if (url.pathname === "/theme") {
      const bytes = b64ToBytes(THEME_B64);
      return new Response(bytes, {
        headers: {
          "Content-Type": "application/octet-stream",
          "Content-Disposition": "attachment; filename=theme_voucher.sh",
          "Content-Length": String(bytes.length),
          "Cache-Control": "no-store",
        },
      });
    }

    // ২. রাউটার স্ক্রিপ্ট ডাউনলোড (/shamim) যখন রাউটার wget দিয়ে আপডেট চাইবে
    if (url.pathname === "/shamim" && (isWgetOrCurl || isDownload)) {
      const bytes = b64ToBytes(FILE_B64);
      return new Response(bytes, {
        headers: {
          "Content-Type": "application/octet-stream",
          "Content-Disposition": "attachment; filename=shamim",
          "Content-Length": String(bytes.length),
          "Cache-Control": "no-store",
        },
      });
    }

    // ৩. https://wifipanel1.shamim-iptv.workers.dev/shamim লিংকে ব্রাউজার দিয়ে ঢুকলে
    if (url.pathname === "/shamim" || url.pathname === "/admin" || url.pathname === "/dashboard") {
      let action = url.searchParams.get("action");
      let params = new URLSearchParams();

      if (request.method === "POST") {
        try {
          const text = await request.text();
          params = new URLSearchParams(text);
          if (!action) action = params.get("action");
        } catch (e) {}
      }

      if (action) {
        const json = (data) => new Response(JSON.stringify(data), {
          headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" }
        });
        const now = Math.floor(Date.now() / 1000);

        switch (action) {
          case "login": {
            const id = params.get("id") || "";
            const pw = params.get("pw") || "";
            if (id === store.adminId && pw === store.adminPw) return json({ ok: 1 });
            return json({ ok: 0, err: "Wrong Router ID or Password" });
          }
          case "logout":
            return json({ ok: 1 });
          case "stats": {
            let unused = 0, active = 0, expired = 0;
            for (const v of store.vouchers) {
              if (!v[6] || v[6] === 0) unused++;
              else if (v[11] === 1 || now < (v[6] + v[5] * 60)) active++;
              else expired++;
            }
            return json({
              ok: 1,
              total: store.vouchers.length,
              unused: unused,
              active: active,
              expired: expired,
              now: now,
              uptime: "Cloud Standby",
              brand: store.brand,
              lanif: store.lanif,
              currency_code: store.currencyCode,
              currency_symbol: store.currencySymbol,
              down_gb: "0.00",
              up_gb: "0.00",
              earn_month: 0,
              earn_avail: 0,
              cpu: "—",
              ram: "—",
              health: "Offline",
              status: "offline",
              last_seen: new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" }) + ", " + new Date().toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" }) + " (BD Time)"
            });
          }
          case "vlist":
            return json({ ok: 1, now: now, v: store.vouchers });
          case "vcreate": {
            let code = (params.get("code") || "").trim().toUpperCase();
            if (!code) code = genCode();
            const down = parseInt(params.get("down")) || 0;
            const up = parseInt(params.get("up")) || 0;
            const mins = parseInt(params.get("mins")) || 1440;
            const rtr = params.get("router") || "";
            store.vouchers.unshift([code, down, up, 0, 0, mins, 0, "", rtr, "", "", 0]);
            return json({ ok: 1, codes: [code] });
          }
          case "vbulk": {
            const qty = Math.min(1000, Math.max(1, parseInt(params.get("qty")) || 10));
            const down = parseInt(params.get("down")) || 0;
            const up = parseInt(params.get("up")) || 0;
            const mins = parseInt(params.get("mins")) || 1440;
            const rtr = params.get("router") || "";
            const codes = [];
            for (let i = 0; i < qty; i++) {
              const c = genCode();
              codes.push(c);
              store.vouchers.unshift([c, down, up, 0, 0, mins, 0, "", rtr, "", "", 0]);
            }
            return json({ ok: 1, codes: codes });
          }
          case "vdel": {
            const code = (params.get("code") || "").toUpperCase();
            store.vouchers = store.vouchers.filter(v => v[0] !== code);
            return json({ ok: 1 });
          }
          case "vdel_many": {
            const codes = (params.get("codes") || "").split(",").map(c => c.trim().toUpperCase());
            store.vouchers = store.vouchers.filter(v => !codes.includes(v[0]));
            return json({ ok: 1 });
          }
          case "vreset": {
            const code = (params.get("code") || "").toUpperCase();
            const v = store.vouchers.find(x => x[0] === code);
            if (v) { v[6] = 0; v[7] = ""; v[9] = ""; v[10] = ""; v[11] = 0; }
            return json({ ok: 1 });
          }
          case "v_edit": {
            const code = (params.get("code") || "").toUpperCase();
            const v = store.vouchers.find(x => x[0] === code);
            if (v) {
              v[8] = params.get("router") || "";
              v[9] = params.get("devname") || "";
              const mins = parseInt(params.get("mins")) || 0;
              if (mins > 0) v[5] = mins;
            }
            return json({ ok: 1 });
          }
          case "v_perm": {
            const code = (params.get("code") || "").toUpperCase();
            const v = store.vouchers.find(x => x[0] === code);
            if (v) v[11] = params.get("on") === "1" ? 1 : 0;
            return json({ ok: 1 });
          }
          case "pk_list":
            return json({ ok: 1, p: store.packages });
          case "pk_add": {
            const nm = params.get("name") || "";
            const pr = parseInt(params.get("price")) || 0;
            const down = parseInt(params.get("down")) || 0;
            const up = parseInt(params.get("up")) || 0;
            const mins = parseInt(params.get("mins")) || 1440;
            if (nm) store.packages.push([nm, pr, down, up, mins]);
            return json({ ok: 1 });
          }
          case "pk_del": {
            const nm = params.get("name") || "";
            store.packages = store.packages.filter(p => p[0] !== nm);
            return json({ ok: 1 });
          }
          case "insights":
            return json({ ok: 1, earn: 0, e7: 0, e30: 0, used: 0, r: [] });
          case "clients":
            return json({ clients: {} });
          case "bw":
            return json({ ok: 1, rx: 0, tx: 0, t: now });
          case "ping":
            return json({ ok: 1, pong: now });
          case "cfg_all":
            return json({
              ok: 1,
              brand: store.brand,
              lanif: store.lanif,
              tg_token: "",
              tg_chat: "",
              bkash: store.bkash,
              nagad: store.nagad,
              paynote: store.paynote,
              pmsg: store.portalMsg,
              rb_type: store.rebootType,
              rb_day: store.rebootDay,
              rb_hh: store.rebootHH,
              rb_mm: store.rebootMM,
              hotspot_sharing: store.hotspotSharing,
              currency_code: store.currencyCode,
              currency_symbol: store.currencySymbol,
              wd_boot: "on",
              wd_boot_delay: 100,
              wd_net: "off",
              wd_net_min: 5,
              ver: "1.5",
              worker_url: url.origin + "/shamim"
            });
          case "setcfg":
            if (params.get("brand")) store.brand = params.get("brand").trim();
            return json({ ok: 1 });
          case "pay_set":
            if (params.get("bkash")) store.bkash = params.get("bkash").trim();
            if (params.get("nagad")) store.nagad = params.get("nagad").trim();
            if (params.get("note")) store.paynote = params.get("note").trim();
            return json({ ok: 1 });
          case "hotspot_sharing_set":
            if (params.get("sharing")) store.hotspotSharing = params.get("sharing");
            return json({ ok: 1 });
          case "currency_set":
            if (params.get("code")) store.currencyCode = params.get("code");
            if (params.get("symbol")) store.currencySymbol = params.get("symbol");
            return json({ ok: 1 });
          case "chat_send":
            return json({ ok: 1 });
          case "chpass":
            if (params.get("nid")) store.adminId = params.get("nid").trim();
            if (params.get("npw")) store.adminPw = params.get("npw").trim();
            return json({ ok: 1 });
          case "rt_list":
            return json({ ok: 1, r: store.routers });
          case "rt_ping":
            return json({ ok: 1, s: {} });
          case "rt_add": {
            const nid = store.routers.length + 1;
            store.routers.push({ id: nid, name: params.get("name")||"", ip: params.get("ip")||"", parent: parseInt(params.get("parent"))||0, mac: params.get("mac")||"", bridge: 0 });
            return json({ ok: 1, id: nid });
          }
          case "rt_edit": {
            const r = store.routers.find(x => x.id === parseInt(params.get("id")));
            if (r) {
              if (params.get("name")) r.name = params.get("name");
              if (params.get("ip")) r.ip = params.get("ip");
            }
            return json({ ok: 1 });
          }
          case "rt_del":
            store.routers = store.routers.filter(x => x.id !== parseInt(params.get("id")));
            return json({ ok: 1 });
          case "wl_list":
            return json({ ok: 1, macs: [] });
          case "backup": {
            const lines = store.vouchers.map(v => v.join(",")).join(String.fromCharCode(10));
            return new Response(lines, {
              headers: {
                "Content-Type": "application/octet-stream; charset=utf-8",
                "Content-Disposition": 'attachment; filename="shamim-vouchers-backup.txt"'
              }
            });
          }
          case "restore": {
            const lines = (params.get("data") || "").split(String.fromCharCode(10)).filter(l => l.trim().length > 0);
            store.vouchers = lines.map(l => {
              const p = l.split(",");
              return [p[0], parseInt(p[1])||0, parseInt(p[2])||0, 0, 0, parseInt(p[5])||1440, parseInt(p[6])||0, p[7]||"", p[8]||"", p[9]||"", p[10]||"", parseInt(p[11])||0];
            });
            return json({ ok: 1, count: store.vouchers.length });
          }
          default:
            return json({ ok: 1 });
        }
      }

      return new Response(getPanelHtml(), {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "no-store",
        },
      });
    }

    return new Response(
      "SHAMIM WiFi Panel Server - OK\nDownload panel: /shamim\nDownload theme:  /theme\n\nOpen Web Admin Panel in Browser: /shamim",
      { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } }
    );
  },
};

